//! 🧪️ Actual original caller, decoder and allocator witness keep every task ingress frontier persistent.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,RetainedCloneGrant,JobOutcomeBorrow,JobOutcomeDescriptor,JobOutcomeView};
fn law()->serde_json::Value{serde_json::from_str(include_str!("../🔣️.json")).unwrap()}
fn stock()->RetainedCloneGrant{static STOCK:std::sync::OnceLock<RetainedCloneGrant>=std::sync::OnceLock::new();*STOCK.get_or_init(||{let law=law();let q=&law["stock"];RetainedCloneGrant{maximum_items:q["items"].as_u64().unwrap()as usize,maximum_copy_bytes:q["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:q["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:q["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:q["depth"].as_u64().unwrap()as usize}})}
fn clock()->Option<u64>{Some(1)}
struct Fixture{caller:Option<OriginalJobFixtureCaller>,decoder:OriginalJobDecodeOwner}
impl Fixture{
 fn new()->Self{Self{caller:Some(OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock(),clock,law()["source"]["deadline"].as_u64().unwrap(),law()["stock"]["fuel"].as_u64().unwrap())),decoder:OriginalJobDecodeOwner::empty()}}
 fn turn<R>(&mut self,grant:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->Result<R,OriginalTurnFailure>{self.caller.as_mut().unwrap().turn_with_decoder(grant,&mut self.decoder,run)}
 fn close(&mut self,producer:&mut OriginalKernelTaskProducer<Input,Job>){producer.begin_close();for _ in 0..64{if producer.terminal_is_empty(){return}let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||self.turn(stock(),|cx|producer.close_step(cx)));let progress=answer.unwrap().progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));}panic!("actual finite task producer did not close its source")}
}
impl Drop for Fixture{fn drop(&mut self){if std::thread::panicking(){return}let caller=self.caller.as_mut().unwrap();for _ in 0..64{if self.decoder.terminal_is_empty(){break}caller.turn(stock(),|cx|cx.with_original_retirement(|cx|{let demand=self.decoder.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,demand,|grant|self.decoder.close_step(grant))?;Ok(())})).unwrap();}assert!(self.decoder.terminal_is_empty());self.caller.take().unwrap().retire(stock());}}
struct Input{bytes:Option<Box<[u8;16]>>}
impl OriginalKernelTaskInput for Input{
 fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{let demand=RetirementDemand{copy_bytes:size_of::<Option<Box<[u8;16]>>>(),release_bytes:16,depth:1,..Default::default()};close_original_retained_step(cx,demand,|_|{drop(self.bytes.take());Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,released_bytes:16,..Default::default()}))})}
 fn terminal_is_empty(&self)->bool{self.bytes.is_none()}
}
struct Job{payload:[u8;16],frame:Option<Box<[u8;32]>>}
impl InteractiveJob for Job{
 fn step<'a>(&'a mut self,cx:&mut StepContext<'_>)->Result<Option<JobOutcomeBorrow<'a>>,OriginalTurnFailure>{assert_eq!(self.payload,[7;16]);cx.consume_fuel(1);Ok(None)}
 fn borrow_outcome<'a>(&'a self,_descriptor:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"constructor fixture has no semantic output"))}
 fn begin_close(&mut self){}
 fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{let demand=RetirementDemand{copy_bytes:size_of::<Option<Box<[u8;32]>>>(),release_bytes:32,depth:1,..Default::default()};close_original_retained_step(cx,demand,|_|{drop(self.frame.take());Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,released_bytes:32,..Default::default()}))})}
 fn terminal_is_empty(&self)->bool{self.frame.is_none()}
}
fn quote()->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:size_of::<Input>()+size_of::<Job>(),capacity_bytes:32,release_bytes:16,depth:1}}
fn build(mut input:Input,_control:&mut NativeDecodeControl<'_>)->(Job,RetainedCloneProgress){let original=input.bytes.take().unwrap();let payload=*original;drop(original);(Job{payload,frame:Some(Box::new([9;32]))},RetainedCloneProgress{copied_items:1,copied_bytes:quote().copy_bytes,retained_capacity_bytes:32,released_bytes:16})}
fn make_producer(fixture:&mut Fixture)->OriginalKernelTaskProducer<Input,Job>{let mut input=Some(Input{bytes:Some(Box::new([7;16]))});fixture.turn(stock(),|cx|Ok(OriginalKernelTaskProducer::new(input.take().unwrap(),cx))).unwrap()}

#[test]
fn renderer_task_ingress_retains_exact_input_across_five_denials_and_foreign_source(){
 let mut fixture=Fixture::new();let mut producer=make_producer(&mut fixture);let pointer=producer.input().unwrap().bytes.as_ref().unwrap().as_ptr();assert!(!fixture.turn(stock(),|cx|producer.admit(cx,quote(),build)).unwrap());let mut foreign=Fixture::new();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.turn(stock(),|cx|producer.admit(cx,quote(),build)));assert!(answer.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 let q=quote();for denied in[RetainedCloneGrant{maximum_items:0,..stock()},RetainedCloneGrant{maximum_copy_bytes:q.copy_bytes-1,..stock()},RetainedCloneGrant{maximum_capacity_bytes:31,..stock()},RetainedCloneGrant{maximum_release_bytes:15,..stock()},RetainedCloneGrant{maximum_depth:0,..stock()}]{let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||fixture.turn(denied,|cx|producer.admit(cx,q,build)));assert!(!answer.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(producer.input().unwrap().bytes.as_ref().unwrap().as_ptr(),pointer);assert!(producer.candidate().is_none());}
 let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||fixture.turn(stock(),|cx|producer.admit(cx,q,build)));assert!(answer.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(32,16));assert!(producer.committed());assert!(producer.input().is_none());fixture.turn(stock(),|cx|producer.run(cx,|job,cx|job.step(cx).map(|_|()))).unwrap();let frame=producer.candidate().unwrap().frame.as_ref().unwrap().as_ptr();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.turn(stock(),|cx|producer.close_step(cx)));assert!(answer.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));producer.begin_close();for denied in[RetainedCloneGrant{maximum_items:0,..stock()},RetainedCloneGrant{maximum_copy_bytes:0,..stock()},RetainedCloneGrant{maximum_release_bytes:31,..stock()},RetainedCloneGrant{maximum_depth:0,..stock()}]{let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||fixture.turn(denied,|cx|producer.close_step(cx)));assert_eq!(answer.unwrap().progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(producer.candidate().unwrap().frame.as_ref().unwrap().as_ptr(),frame);}assert!(!fixture.turn(stock(),|cx|Ok(cx.original_source_parent()?.original_loans_are_returned())).unwrap());fixture.close(&mut producer);assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(producer)).1.released_bytes,0);
}

#[test]
fn renderer_task_ingress_retains_born_candidate_on_quote_receipt_failure_and_closes_prebirth_cancellation(){
 let mut fixture=Fixture::new();let mut producer=make_producer(&mut fixture);assert!(!fixture.turn(stock(),|cx|producer.admit(cx,quote(),build)).unwrap());let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||fixture.turn(stock(),|cx|producer.admit(cx,OriginalConstructionDemand{capacity_bytes:31,..quote()},build)));let failure=answer.unwrap_err();assert!(failure.primary_receiving().unwrap().quote_refusal.is_some());assert_eq!((heap.requested_bytes,heap.released_bytes),(32,16));assert!(producer.input().is_none());assert!(producer.candidate().is_some());assert!(!producer.committed());assert!(fixture.turn(stock(),|cx|producer.run(cx,|_,_|Ok(()))).is_err());drop(failure);fixture.close(&mut producer);assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(producer)).1.released_bytes,0);
 let mut prebirth=make_producer(&mut fixture);fixture.caller.as_ref().unwrap().cancel().cancel_now();prebirth.begin_close();assert!(!prebirth.committed());fixture.close(&mut prebirth);assert!(prebirth.terminal_is_empty());assert!(fixture.turn(stock(),|cx|Ok(cx.original_source_parent()?.original_loans_are_returned())).unwrap());
}
